const MAX_LEVEL = 50;

function realm55(p) {
  return campRegions.find(z => Math.hypot(p.x-z[2], p.z-z[3]) < z[7])
    || legacyRegions.reduce((a, b) => Math.hypot(p.x-b[2], p.z-b[3]) < Math.hypot(p.x-a[2], p.z-a[3]) ? b : a);
}

function canFightPlayer(p) {
  return p.level >= 60 || (p.level >= MAX_LEVEL && realm55(p)[0] === "ardream");
}

function safe(p) {
  return safeHubs.some(z => Math.hypot(p.x-z[2], p.z-z[3]) < 18)
    || (Math.abs(p.x)>25 && Math.abs(p.x)<39 && Math.abs(p.z)<20)
    || campRegions.some(z => Math.hypot(p.x-z[2], p.z-z[3]) < 10);
}
