for (const [zone, name, level, offsetX, offsetZ, boss] of [
  ['pine', 'Çam Pençesi', 10, 0, 24],
  ['pine', 'Yamaç Nöbetçisi', 15, 0, -28],
  ['pine', 'Boğaz Bekçisi', 19, 30, 0, true],
  ['human', 'Sınır Yağmacısı', 26, 0, -30],
  ['orc', 'Kızıl Vadi Avcısı', 26, 0, -30],
  ['ash', 'Kül Gezgini', 30, 0, 24],
  ['ash', 'Kor Golem', 35, 0, -28],
  ['ash', 'Kül Muhafızı', 39, 30, 0, true],
  ['eslant', 'Rüzgâr Avcısı', 42, 33, 0],
  ['eslant', 'Buz Sırtı Muhafızı', 47, 0, -32],
  ['shard', 'Kristal Nöbetçi', 50, 0, 24],
  ['shard', 'Kristal Hisar Lordu', 50, 32, 0, true],
]) {
  const [, , centerX, centerZ] = regions53.find(z => z[0] === zone);
  const count = boss ? 1 : 5;
  for (let i = 0; i < count; i++) {
    const x = centerX + offsetX + (i % 3 - 1) * 5;
    const z = centerZ + offsetZ + Math.floor(i / 3) * 6;
    const max = (boss ? 350 : 75) + level * (boss ? 54 : 22);
    M.push({id:'mprogress'+M.length, name, level, x, z, homeX:x, homeZ:z, max, hp:max, dead:0, last:0});
  }
}

// JSON content mods extend existing maps without executing uploaded JavaScript.
const modsDirectory = path.resolve(process.env.MODS_DIR || 'mods');
function loadContentMods() {
  if (!fs.existsSync(modsDirectory)) return;
  const validMaps = new Map(regions53.map(region => [region[0], region]));
  const modFiles = fs.readdirSync(modsDirectory).filter(name => name.endsWith('.json')).sort();
  for (const fileName of modFiles) {
    try {
      const mod = JSON.parse(fs.readFileSync(path.join(modsDirectory, fileName), 'utf8'));
      if (!/^[a-z0-9_-]{1,40}$/.test(mod.id || '') || !Array.isArray(mod.creatures)) {
        throw new Error('Mod kimliği veya creatures listesi geçersiz');
      }
      for (const creature of mod.creatures) {
        const region = validMaps.get(creature.map);
        const count = Number(creature.count);
        const level = Number(creature.level);
        const health = Number(creature.health);
        if (!region || typeof creature.name !== 'string' || creature.name.trim().length < 2 || creature.name.length > 32
          || !Number.isInteger(count) || count < 1 || count > 20
          || !Number.isInteger(level) || level < 1 || level > 50
          || !Number.isInteger(health) || health < 30 || health > 10000) {
          throw new Error('Yaratık verisi geçersiz veya desteklenmeyen harita seçildi');
        }
        for (let i = 0; i < count; i++) {
          const angle = (Math.PI * 2 * i) / count;
          const radius = 22 + Math.floor(i / 8) * 5;
          const x = region[2] + Math.cos(angle) * radius;
          const z = region[3] + Math.sin(angle) * radius;
          M.push({id:'m_mod_'+mod.id+'_'+M.length,name:creature.name.trim(),level,x,z,homeX:x,homeZ:z,max:health,hp:health,dead:0,last:0,modId:mod.id});
        }
      }
      console.log('Mod yüklendi: '+mod.id+' ('+fileName+')');
    } catch (error) {
      console.error('Mod yüklenemedi ('+fileName+'): '+error.message);
    }
  }
}
loadContentMods();

